// The Round-1 fuzz corpus: everyday / typos / numbers / hostile rows authored
// in the August 2026 campaign (docs/qa/fuzz-campaign-2026-08.md). This Swift
// file is the source of truth — the JSON corpora and generator script it was
// first mechanized from were never checked in. Edit rows in place.
import Foundation

/// One corpus row: an utterance, an optional state/clock precondition in the
/// expectation mini-grammar, and the expected outcome. Interpreted at test
/// runtime by FuzzCorpusR1.swift.
struct FuzzCorpusRow: Sendable, CustomStringConvertible {
    let source: String
    let index: Int
    let utterance: String
    let stateSpec: String?
    let expect: String

    /// Stable, readable test-case name: source#index plus a sanitized prefix
    /// of the utterance (control characters and non-ASCII shown as dots).
    var description: String {
        let printable = utterance.unicodeScalars.prefix(40).map { s -> Character in
            (0x20...0x7E).contains(Int(s.value)) ? Character(s) : "\u{B7}"
        }
        return "\(source)#\(index) \(String(printable))"
    }
}

